import {
  forwardRef,
  useId,
  type ReactNode,
  type SelectHTMLAttributes,
} from "react";
import "./LayeredSelect.css";

export type LayeredSelectTone =
  | "neutral"
  | "copper"
  | "green"
  | "gold";

export type LayeredSelectSize =
  | "small"
  | "medium"
  | "large";

export interface LayeredSelectProps
  extends Omit<SelectHTMLAttributes<HTMLSelectElement>, "size"> {
  label: ReactNode;
  children: ReactNode;
  description?: ReactNode;
  error?: ReactNode;
  tone?: LayeredSelectTone;
  selectSize?: LayeredSelectSize;
  fullWidth?: boolean;
}

export const LayeredSelect = forwardRef<HTMLSelectElement, LayeredSelectProps>(
  function LayeredSelect(
    {
      label,
      children,
      description,
      error,
      tone = "neutral",
      selectSize = "medium",
      fullWidth = false,
      className = "",
      id,
      disabled,
      required,
      multiple,
      ...props
    },
    ref
  ) {
    const generatedId = useId();
    const selectId = id || `layered-select-${generatedId}`;
    const descriptionId = description ? `${selectId}-description` : undefined;
    const errorId = error ? `${selectId}-error` : undefined;

    const describedBy =
      [props["aria-describedby"], descriptionId, errorId]
        .filter(Boolean)
        .join(" ") || undefined;

    const isInvalid =
      Boolean(error) ||
      props["aria-invalid"] === true ||
      props["aria-invalid"] === "true";

    const wrapperClasses = [
      "layered-select-wrapper",
      fullWidth ? "layered-select-wrapper--full-width" : "",
      multiple ? "layered-select-wrapper--multiple" : "",
      className,
    ]
      .filter(Boolean)
      .join(" ");

    return (
      <div
        className={wrapperClasses}
        data-tone={tone}
        data-size={selectSize}
        data-disabled={disabled ? "true" : undefined}
        data-invalid={isInvalid ? "true" : undefined}
        data-multiple={multiple ? "true" : undefined}
      >
        <div className="layered-select__label-row">
          <label htmlFor={selectId} className="layered-select__label">
            {label}
            {required && (
              <span className="layered-select__required" aria-hidden="true">
                {" *"}
              </span>
            )}
          </label>
        </div>

        <div className="layered-select__casing">
          <div className="layered-select__surface">
            <select
              ref={ref}
              id={selectId}
              disabled={disabled}
              required={required}
              multiple={multiple}
              aria-describedby={describedBy}
              aria-invalid={isInvalid ? true : undefined}
              className="layered-select__control"
              {...props}
            >
              {children}
            </select>

            {!multiple && (
              <span className="layered-select__arrow" aria-hidden="true">
                <svg
                  width="12"
                  height="8"
                  viewBox="0 0 12 8"
                  fill="none"
                  xmlns="http://www.w3.org/2000/svg"
                >
                  <path
                    d="M1 1.5L6 6.5L11 1.5"
                    stroke="currentColor"
                    strokeWidth="2"
                    strokeLinecap="round"
                    strokeLinejoin="round"
                  />
                </svg>
              </span>
            )}
          </div>
        </div>

        {description && (
          <div id={descriptionId} className="layered-select__description">
            {description}
          </div>
        )}

        {error && (
          <div id={errorId} className="layered-select__error" role="alert">
            {error}
          </div>
        )}
      </div>
    );
  }
);

.layered-select-wrapper {
    /* Default neutral tone */
    --select-tone-accent: #8c8f94;
    --select-tone-focus: var(--control-focus);

    /* Default medium size */
    --select-font-size: 0.95rem;
    --select-label-font-size: 0.875rem;
    --select-padding-y: 9px;
    --select-padding-x: 14px;
    --select-surface-height: 44px;

    display: inline-flex;
    flex-direction: column;
    gap: 6px;
    box-sizing: border-box;

    width: 100%;
    max-width: 420px;

    color: var(--color-text);
}

.layered-select-wrapper--full-width {
    max-width: none;
}

/* Label Row & Label */

.layered-select__label-row {
    display: flex;
    align-items: center;
    justify-content: space-between;
}

.layered-select__label {
    color: var(--color-text);

    font-size: var(--select-label-font-size);
    font-weight: 600;
    line-height: 1.3;
    letter-spacing: 0.015em;

    transition: color var(--duration-fast) var(--ease-control);
}

.layered-select__required {
    color: var(--select-tone-accent);
}

/* Outer Structural Casing */

.layered-select__casing {
    box-sizing: border-box;

    padding: 3px;
    border: 2px solid var(--control-shell-border);
    border-radius: var(--control-radius-outer);

    background:
        linear-gradient(180deg,
            var(--input-casing-top) 0%,
            var(--input-casing-bottom) 100%);

    box-shadow:
        0 2px 5px rgb(0 0 0 / 30%),
        inset 0 1px rgb(255 255 255 / 6%);

    transition:
        box-shadow var(--duration-fast) var(--ease-control),
        border-color var(--duration-fast) var(--ease-control),
        outline var(--duration-fast) var(--ease-control);
}

/* Inner Recessed Surface */

.layered-select__surface {
    position: relative;
    display: flex;
    align-items: center;
    box-sizing: border-box;

    min-height: var(--select-surface-height);

    border: 2px solid var(--control-trench);
    border-radius: var(--control-radius-inner);

    background:
        linear-gradient(180deg,
            var(--input-surface-bg-top) 0%,
            var(--input-surface-bg-bottom) 100%);

    color: var(--color-text);

    box-shadow:
        inset 0 2px 4px rgb(0 0 0 / 50%),
        inset 0 -1px 1px rgb(255 255 255 / 3%);

    transition:
        border-color var(--duration-fast) var(--ease-control),
        box-shadow var(--duration-fast) var(--ease-control),
        background var(--duration-fast) var(--ease-control);

    overflow: hidden;
}

/* Native Select Control */

.layered-select__control {
    width: 100%;

    padding: var(--select-padding-y) 38px var(--select-padding-y) var(--select-padding-x);
    border: none;
    outline: none;

    background: transparent;
    color: var(--color-text);

    font-family: inherit;
    font-size: var(--select-font-size);
    line-height: 1.4;

    cursor: pointer;

    text-overflow: ellipsis;
    white-space: nowrap;
    overflow: hidden;

    appearance: none;
    -webkit-appearance: none;
    -moz-appearance: none;

    box-sizing: border-box;
}

.layered-select__control option,
.layered-select__control optgroup {
    background-color: var(--input-surface-bg-bottom);
    color: var(--color-text);

    padding: 6px 10px;
}

/* Decorative Arrow */

.layered-select__arrow {
    position: absolute;
    right: 14px;
    top: 50%;
    transform: translateY(-50%);

    display: flex;
    align-items: center;
    justify-content: center;

    color: var(--color-text-muted);
    pointer-events: none;

    transition: color var(--duration-fast) var(--ease-control);
}

/* Supporting Text & Error Text */

.layered-select__description {
    margin-top: 2px;
    color: var(--color-text-muted);

    font-size: 0.8rem;
    line-height: 1.4;
}

.layered-select__error {
    margin-top: 2px;
    color: var(--control-error-text, var(--control-error));

    font-size: 0.8rem;
    font-weight: 500;
    line-height: 1.4;
}

/* Multiple Select Overrides */

.layered-select-wrapper[data-multiple="true"] .layered-select__surface {
    min-height: auto;
}

.layered-select-wrapper[data-multiple="true"] .layered-select__control {
    appearance: auto;
    -webkit-appearance: auto;
    -moz-appearance: auto;

    padding: 8px;
    min-height: 110px;
    height: auto;

    white-space: normal;
    text-overflow: clip;
    overflow-y: auto;
}

/* Tone Variants */

.layered-select-wrapper[data-tone="copper"] {
    --select-tone-accent: var(--tone-copper-light);
    --select-tone-focus: var(--tone-copper-light);
}

.layered-select-wrapper[data-tone="green"] {
    --select-tone-accent: var(--tone-green-light);
    --select-tone-focus: var(--tone-green-light);
}

.layered-select-wrapper[data-tone="gold"] {
    --select-tone-accent: var(--tone-gold-light);
    --select-tone-focus: var(--tone-gold-light);
}

.layered-select-wrapper[data-tone="neutral"] {
    --select-tone-accent: var(--tone-neutral-light);
    --select-tone-focus: var(--control-focus);
}

/* Size Variants */

.layered-select-wrapper[data-size="small"] {
    --select-font-size: 0.85rem;
    --select-label-font-size: 0.8rem;
    --select-padding-y: 6px;
    --select-padding-x: 10px;
    --select-surface-height: 36px;
}

.layered-select-wrapper[data-size="medium"] {
    --select-font-size: 0.95rem;
    --select-label-font-size: 0.875rem;
    --select-padding-y: 9px;
    --select-padding-x: 14px;
    --select-surface-height: 44px;
}

.layered-select-wrapper[data-size="large"] {
    --select-font-size: 1.05rem;
    --select-label-font-size: 0.95rem;
    --select-padding-y: 12px;
    --select-padding-x: 18px;
    --select-surface-height: 52px;
}

/* Interaction & States */

/* Hover */
.layered-select-wrapper:not([data-disabled="true"]):hover .layered-select__casing {
    box-shadow:
        0 3px 8px rgb(0 0 0 / 40%),
        inset 0 1px rgb(255 255 255 / 9%);
}

.layered-select-wrapper:not([data-disabled="true"]):hover .layered-select__surface {
    border-color: #2a221c;
}

.layered-select-wrapper:not([data-disabled="true"]):hover .layered-select__arrow {
    color: var(--color-text);
}

/* Focus */
.layered-select-wrapper:not([data-disabled="true"]):focus-within .layered-select__casing {
    outline: 3px solid var(--select-tone-focus);
    outline-offset: 2px;
}

.layered-select-wrapper:not([data-disabled="true"]):focus-within .layered-select__surface {
    border-color: var(--select-tone-focus);
    box-shadow:
        0 0 0 1px var(--select-tone-focus),
        inset 0 2px 4px rgb(0 0 0 / 60%);
}

.layered-select-wrapper:not([data-disabled="true"]):focus-within .layered-select__arrow {
    color: var(--select-tone-focus);
}

/* Disabled State */
.layered-select-wrapper[data-disabled="true"] {
    opacity: 0.5;
    filter: grayscale(0.45);
    cursor: not-allowed;
}

.layered-select-wrapper[data-disabled="true"] .layered-select__control,
.layered-select-wrapper[data-disabled="true"] .layered-select__label {
    cursor: not-allowed;
}

.layered-select-wrapper[data-disabled="true"] .layered-select__surface {
    background: #141516;
}

/* Error State (takes priority over selected tone) */
.layered-select-wrapper[data-invalid="true"] .layered-select__label {
    color: var(--control-error);
}

.layered-select-wrapper[data-invalid="true"] .layered-select__surface {
    border-color: var(--control-error);
}

.layered-select-wrapper[data-invalid="true"]:focus-within .layered-select__casing {
    outline-color: var(--control-error);
}

.layered-select-wrapper[data-invalid="true"]:focus-within .layered-select__surface {
    border-color: var(--control-error);
    box-shadow:
        0 0 0 1px var(--control-error),
        inset 0 2px 4px rgb(0 0 0 / 60%);
}

.layered-select-wrapper[data-invalid="true"] .layered-select__arrow {
    color: var(--control-error);
}

/* Responsive Narrow Screen Support */

@media (max-width: 640px) {
    .layered-select-wrapper {
        max-width: 100%;
    }
}

/* Reduced Motion */

@media (prefers-reduced-motion: reduce) {
    .layered-select-wrapper,
    .layered-select__casing,
    .layered-select__surface,
    .layered-select__label,
    .layered-select__arrow {
        transition: none;
    }
}
